const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

if (data.length === 0) process.exit(0);

const N = data[0];
const M = data[1];
const adj = new Array(N).fill(0);

let p = 2;
for (let i = 0; i < M; i++) {
    const x = data[p++] - 1;
    const y = data[p++] - 1;
    adj[x] |= 1 << y;
    adj[y] |= 1 << x;
}

const total = 1 << N;
const valid = new Uint8Array(total);
valid[0] = 1;

let answer = 0;

for (let mask = 1; mask < total; mask++) {
    const low = mask & -mask;
    const v = 31 - Math.clz32(low);
    const rest = mask ^ low;

    if (valid[rest] && (adj[v] & rest) === 0) {
        valid[mask] = 1;
        answer++;
    }
}

console.log(answer);
